<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class MovimientoInventario extends Model { protected $table='movimientos_inventario'; protected $guarded=[]; protected $casts=['fecha'=>'datetime']; public function documento(){return $this->belongsTo(Documento::class);} public function producto(){return $this->belongsTo(Producto::class);} public function bodega(){return $this->belongsTo(Bodega::class);} public function detalle(){return $this->belongsTo(DocumentoDetalle::class,'documento_detalle_id');} }
